import React, { Component } from "react";
import "./Signup.css";
import FormJson from "./formid";

export default class Signup extends Component {
    render() {
        const signData = FormJson.find(item => item.formId === 2);
        const contentSign = signData.content;

        return (
            <div className="content-container">
                <div className="formbox">
                    <div className="button-box">
                        <div id="btn"></div>
                        <button type="button" className="toggle-btn">Log In</button>
                        <button type="button" className="toggle-btn">Sign Up</button> 
                    </div>
                    <div className="social-icons">
                        <img src="fb.png" alt="Facebook" />
                        <img src="gb.png" alt="Google" />
                    </div>
                    <form className="input-group">
                        <div className="input-left">
                            <input type="text" className="input-field" placeholder="Full Name" required />
                            <input type="password" className="input-field" placeholder="Password" required />
                            <input type="text" className="input-field" placeholder="City" required />
                            <input type="text" className="input-field" placeholder="Microchip Number" required/>
                            <input type="text" className="input-field" placeholder="Animal Color" required />

                        </div>


                        <div className="input-right">
                           <input type="text" className="input-field" placeholder="Email" required />
                           <input type="password" className="input-field" placeholder="Confirm Password" required />
                           <input type="text" className="input-field" placeholder="Phone Number" required />
                           <input type="text" className="input-field" placeholder="Animal Kind" required />
                        </div>

                    </form>
                    <button type="submit" className="submit-btn">Sign Up</button>

                </div>
            </div>
        );
    }
}
